5	/// Connection lifecycle for one robot: handshake, health polling, wake/sleep and recorded moves.
6	@MainActor
7	@Observable
8	public final class RobotSession {
9	    public enum ConnectionPhase: Equatable, Sendable {
10	        case idle
11	        case connecting
12	        case connected(RobotIdentity)
13	        case unreachable(RobotIdentity)
14	    }
15	
16	    public struct MovePlayback: Equatable, Sendable {
17	        public let dataset: String
18	        public let move: String
19	        public let uuid: String
20	    }
21	
22	    public struct Configuration: Sendable {
23	        /// Upstream polls every 3 s (5 s over robot Wi-Fi).
24	        public var pollInterval: Duration = .seconds(3)
25	        /// Consecutive successful probes required to leave `.unreachable`.
26	        public var requiredConsecutiveSuccesses = 2
27	        /// Move task polling is intentionally cheaper than rendering/state streaming.
28	        public var movePollInterval: Duration = .milliseconds(500)
29	
30	        public init() {}
31	    }
32	
33	    public private(set) var phase: ConnectionPhase = .idle
34	    public private(set) var address: RobotAddress?
35	    public private(set) var lastStatus: Components.Schemas.DaemonStatus?
36	    public private(set) var lastError: String?
37	    public private(set) var compatibilityWarning: String?
38	    public private(set) var currentMove: MovePlayback?
39	    public private(set) var isStoppingMove = false
40	    /// Explicit Disconnect suppresses discovery-driven reconnect until the user connects again.
41	    public private(set) var automaticConnectionAllowed = true
42	
43	    private let configuration: Configuration
44	    private let makeClient: @Sendable (RobotAddress) throws -> any RobotAPIClient
45	    private var client: (any RobotAPIClient)?
46	    private var pollTask: Task<Void, Never>?
47	    private var movePollTask: Task<Void, Never>?
48	    private var pathMonitor: NWPathMonitor?
49	    private var moveCache: [String: [String]] = [:]
50	    private var connectionAttemptID = UUID()
51	
52	    /// Production session talking to a real daemon.
53	    public convenience init(configuration: Configuration = .init()) {
54	        self.init(configuration: configuration) { try RobotConnection(address: $0) }
55	    }
56	
57	    /// Injectable client factory for tests.
58	    public init(
59	        configuration: Configuration = .init(),
60	        makeClient: @escaping @Sendable (RobotAddress) throws -> any RobotAPIClient
61	    ) {
62	        self.configuration = configuration
63	        self.makeClient = makeClient
64	    }
65	
66	    /// Connects manually by default. Automatic attempts respect a preceding explicit Disconnect.
67	    @discardableResult
68	    public func connect(to address: RobotAddress, automatically: Bool = false) async -> Bool {
69	        guard !automatically || automaticConnectionAllowed else { return false }
70	        if !automatically {
71	            automaticConnectionAllowed = true
72	        }
73	
74	        let attemptID = UUID()
75	        connectionAttemptID = attemptID
76	        resetConnectionState()
77	        self.address = address
78	        phase = .connecting
79	        lastError = nil
80	
81	        do {
82	            let client = try makeClient(address)
83	            let handshake = try await client.handshake()
84	            guard connectionAttemptID == attemptID, !Task.isCancelled else {
85	                if connectionAttemptID == attemptID {
86	                    resetConnectionState()
87	                }
88	                return false
89	            }
90	            self.client = client
91	            lastStatus = handshake.status
92	            compatibilityWarning = handshake.compatibility.warningMessage
93	            phase = .connected(handshake.identity)
94	            KnownRobots.lastAddress = address
95	            startPolling(identity: handshake.identity)
96	            startPathMonitor(identity: handshake.identity)
97	            return true
98	        } catch {
99	            guard connectionAttemptID == attemptID else { return false }
100	            resetConnectionState()
101	            if !Task.isCancelled {
102	                lastError = "\(error)"
103	            }
104	            return false
105	        }
106	    }
107	
108	    public func disconnect() {
109	        automaticConnectionAllowed = false
110	        connectionAttemptID = UUID()
111	        resetConnectionState()
112	        lastError = nil
113	    }
114	
115	    public func wake() async {
116	        await run { try await $0.wakeUp() }
117	    }
118	
119	    public func sleep() async {
120	        await run { try await $0.gotoSleep() }
121	    }
122	
123	    /// Returns a session-scoped cached dataset index. Actual move assets stay daemon-side.
124	    public func moves(in dataset: String, refresh: Bool = false) async throws -> [String] {
125	        if !refresh, let cached = moveCache[dataset] {
126	            return cached
127	        }
128	        guard let client else { throw ReachyKitError.notConnected }
129	        do {
130	            let moves = try await client.listMoves(dataset: dataset)
131	            moveCache[dataset] = moves
132	            lastError = nil
133	            return moves
134	        } catch {
135	            lastError = "\(error)"
136	            throw error
137	        }
138	    }
139	
140	    public func playMove(dataset: String, move: String) async throws {
141	        guard let client else { throw ReachyKitError.notConnected }
142	        if currentMove != nil {
143	            await stopMove()
144	        }
145	        lastError = nil
146	        do {
147	            let uuid = try await client.playMove(dataset: dataset, move: move)
148	            let playback = MovePlayback(dataset: dataset, move: move, uuid: uuid)
149	            currentMove = playback
150	            startMonitoring(playback, client: client)
151	        } catch {
152	            lastError = "\(error)"
153	            throw error
154	        }
155	    }
156	
157	    /// Stops both daemon tasks: motion and the separately-owned sound player.
158	    public func stopMove() async {
159	        guard let client, let playback = currentMove, !isStoppingMove else { return }
160	        isStoppingMove = true
161	        movePollTask?.cancel()
162	        movePollTask = nil
163	
164	        let errors = await withTaskGroup(of: String?.self, returning: [String].self) { group in
165	            group.addTask {
166	                do {
167	                    try await client.stopMove(uuid: playback.uuid)
168	                    return nil
169	                } catch {
170	                    return "Move: \(error)"
171	                }
172	            }
173	            group.addTask {
174	                do {
175	                    try await client.stopSound()
176	                    return nil
177	                } catch {
178	                    return "Sound: \(error)"
179	                }
180	            }
181	
182	            var errors: [String] = []
183	            for await error in group {
184	                if let error {
185	                    errors.append(error)
186	                }
187	            }
188	            return errors
189	        }
190	
191	        if currentMove?.uuid == playback.uuid {
192	            currentMove = nil
193	        }
194	        isStoppingMove = false
195	        lastError = errors.isEmpty ? nil : errors.sorted().joined(separator: "\n")
196	    }
197	
198	    private func run(_ operation: (any RobotAPIClient) async throws -> Void) async {
199	        guard let client else { return }
200	        lastError = nil
201	        do {
202	            try await operation(client)
203	        } catch {
204	            lastError = "\(error)"
205	        }
206	    }
207	
208	    private func resetConnectionState() {
209	        pollTask?.cancel()
210	        pollTask = nil
211	        movePollTask?.cancel()
212	        movePollTask = nil
213	        pathMonitor?.cancel()
214	        pathMonitor = nil
215	        client = nil
216	        address = nil
217	        lastStatus = nil
218	        compatibilityWarning = nil
219	        currentMove = nil
220	        isStoppingMove = false
221	        moveCache = [:]
222	        phase = .idle
223	    }
224	
225	    /// Polls the daemon's authoritative running-task list so natural completion
226	    /// clears the UI. Two misses avoid racing task registration just after play.
227	    private func startMonitoring(_ playback: MovePlayback, client: any RobotAPIClient) {
228	        movePollTask?.cancel()
229	        movePollTask = Task { [configuration] in
230	            var consecutiveMisses = 0
231	            while !Task.isCancelled, currentMove?.uuid == playback.uuid {
232	                try? await Task.sleep(for: configuration.movePollInterval)
233	                guard !Task.isCancelled, currentMove?.uuid == playback.uuid else { return }
234	                do {
235	                    let running = try await client.runningMoveUUIDs()
236	                    guard !Task.isCancelled, currentMove?.uuid == playback.uuid else { return }
237	                    if running.contains(playback.uuid) {
238	                        consecutiveMisses = 0
239	                    } else {
240	                        consecutiveMisses += 1
241	                        if consecutiveMisses >= 2 {
242	                            try? await client.stopSound()
243	                            guard !Task.isCancelled, currentMove?.uuid == playback.uuid else { return }
244	                            currentMove = nil
245	                            movePollTask = nil
246	                            return
247	                        }
248	                    }
249	                } catch {
250	                    // A transient status failure must not claim that playback ended.
251	                }
252	            }
253	        }
254	    }
255	
256	    /// Network changes shouldn't wait for the next poll tick: losing the path
257	    /// drops to `.unreachable` immediately; regaining it restarts polling now.
258	    private func startPathMonitor(identity: RobotIdentity) {
259	        pathMonitor?.cancel()
260	        let monitor = NWPathMonitor()
261	        monitor.pathUpdateHandler = { [weak self] path in
262	            let satisfied = path.status == .satisfied
263	            Task { @MainActor in
264	                self?.pathChanged(satisfied: satisfied, identity: identity)
265	            }
266	        }
267	        monitor.start(queue: .main)
268	        pathMonitor = monitor
269	    }
270	
271	    private func pathChanged(satisfied: Bool, identity: RobotIdentity) {
272	        guard client != nil else { return }
273	        if !satisfied {
274	            if case .connected = phase {
275	                phase = .unreachable(identity)
276	            }
277	        } else if case .unreachable = phase {
278	            startPolling(identity: identity)
279	        }
280	    }
281	
282	    private func startPolling(identity: RobotIdentity) {
283	        pollTask?.cancel()
284	        pollTask = Task { [configuration] in
285	            var consecutiveSuccesses = 0
286	            while !Task.isCancelled {
287	                try? await Task.sleep(for: configuration.pollInterval)
288	                guard !Task.isCancelled, let client = self.client else { return }
289	                do {
290	                    let status = try await client.daemonStatus()
291	                    lastStatus = status
292	                    if case .unreachable = phase {
293	                        consecutiveSuccesses += 1
294	                        if consecutiveSuccesses >= configuration.requiredConsecutiveSuccesses {
295	                            phase = .connected(identity)
296	                        }
297	                    } else {
298	                        consecutiveSuccesses = 1
299	                    }
300	                } catch {
301	                    consecutiveSuccesses = 0
302	                    phase = .unreachable(identity)
303	                }
304	            }
305	        }
306	    }
307	}
