/// Wake-up is a sequence, not a single call: `/move/play/wake_up` plays an
/// animation but never touches the motor mode, and it answers 503 while the
/// backend is down. A robot left in `disabled` therefore stays limp.
///
/// TODO: implement the sequence.
///
/// Both branches are already available on `client`:
///
/// - Backend not running (`lastStatus?.state != .running`): a single
///   `startDaemon(wakeUp: true)` makes the daemon enable the motors and play
///   the animation itself. It returns immediately (background job), so follow
///   it with `waitForDaemonRunning()`.
/// - Backend running: `setMotorMode(.enabled)`, wait
///   `configuration.motorSettleDelay`, then `wakeUp()`.
///
/// Report failures through `lastError` the way `sleep()` below does.
public func wake() async {
    guard let client else { return }
    lastError = nil
    _ = client
}

/// Mirror image of wake: the animation must finish *before* power is cut,
/// otherwise the head drops wherever it happens to be.
public func sleep() async {
    guard let client else { return }
    lastError = nil
    do {
        let uuid = try await client.gotoSleep()
        await waitForMoveToFinish(uuid, client: client)
        try await client.setMotorMode(.disabled)
    } catch {
        lastError = "\(error)"
    }
}

/// Polls the daemon's authoritative running-move list until `uuid` is gone.
/// A timeout returns normally: parking the motors matters more than proof
/// that the animation ran to completion.
private func waitForMoveToFinish(_ uuid: String, client: any RobotAPIClient) async {
    let deadline = ContinuousClock.now + configuration.moveCompletionTimeout
    while ContinuousClock.now < deadline, !Task.isCancelled {
        try? await Task.sleep(for: configuration.movePollInterval)
        guard let running = try? await client.runningMoveUUIDs() else { continue }
        if !running.contains(uuid) { return }
    }
}

/// Waits out the background start job, refreshing `lastStatus` as it goes.
@discardableResult
private func waitForDaemonRunning(client: any RobotAPIClient) async -> Bool {
    let deadline = ContinuousClock.now + configuration.daemonStartTimeout
    while ContinuousClock.now < deadline, !Task.isCancelled {
        try? await Task.sleep(for: configuration.pollInterval)
        guard let status = try? await client.daemonStatus() else { continue }
        lastStatus = status
        switch status.state {
        case .running: return true
        case .error, .stopped: return false
        default: continue
        }
    }
    return false
}

